import { useQuery, useMutation } from "@tanstack/react-query";
import { useAppDispatch } from "../../../app/store/hooks";
import { setMeals } from "../../../app/store/slices/mealsSlice";
import {
  fetchMealsApi,
  addMealApi,
  deleteMealApi,
} from "../../api/mealsApi";

export const useMeals = (date, token) => {
  const dispatch = useAppDispatch();

  // 🔹 Получение списка еды
  const { data: rows = [], isLoading: loading } = useQuery(
    ["meals", date],
    () => fetchMealsApi(token, date),
    {
      onSuccess: (data) => dispatch(setMeals({ date, meals: data })),
      enabled: !!token,
    }
  );

  // 🔹 Добавление еды
  const addMealMutation = useMutation(
    ({ mealId, amount }) => addMealApi(token, mealId, amount),
    {
      onSuccess: () => fetchMealsApi(token, date),
    }
  );

  // 🔹 Удаление еды
  const deleteMealMutation = useMutation(
    (mealId) => deleteMealApi(token, mealId),
    {
      onSuccess: () => fetchMealsApi(token, date),
    }
  );

  const handleAddMeal = (mealId, amount) => {
    addMealMutation.mutate({ mealId, amount });
  };

  const handleDeleteMeal = (mealId) => {
    deleteMealMutation.mutate(mealId);
  };

  return { rows, loading, handleAddMeal, handleDeleteMeal };
};
